from collections import namedtuple
from decimal import Decimal
from fractions import Fraction
Point = namedtuple('Point', 'x')
class Counter:
    def tags(self):
        return {'a', 'b'}
    def blob(self):
        return b'xy'
    def point(self):
        return Point(3)
    def has(self, items):
        return 'a' in items
    def same(self):
        return self
    def amount(self):
        return Decimal('1.50')
    def ratio(self):
        return Fraction(1, 3)
